'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var tryRequire = require( '@stdlib/utils/try-require' );
var NINF = require( '@stdlib/constants/float64/ninf' );


// VARIABLES //

var pdf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( pdf instanceof Error )
};


// FIXTURES //

var small = require( './fixtures/python/small_values.json' );
var medium = require( './fixtures/python/medium_values.json' );
var large = require( './fixtures/python/large_values.json' );


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof pdf, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the function returns `NaN`', opts, function test( t ) {
	var y;

	y = pdf( NaN, 1.0, 1.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	y = pdf( 0.1, NaN, 1.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	y = pdf( 0.1, 0.1, NaN );
	t.equal( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided `alpha <= 0`, the function returns `NaN`', opts, function test( t ) {
	var y;

	y = pdf( 1.0, 0.0, 0.1 );
	t.equal( isnan( y ), true, 'returns expected value' );

	y = pdf( 0.5, -1.0, 0.1 );
	t.equal( isnan( y ), true, 'returns expected value' );

	y = pdf( 1.0, NINF, 0.1 );
	t.equal( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided `beta <= 0`, the function returns `NaN`', opts, function test( t ) {
	var y;

	y = pdf( 1.0, 0.1, 0.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	y = pdf( 0.5, 0.1, -1.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	y = pdf( 1.0, 0.1, NINF );
	t.equal( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a nonpositive number for `x` and a valid `alpha` and `beta`, the function returns `NaN`', opts, function test( t ) {
	var y;

	y = pdf( 0.0, 0.1, 1.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	y = pdf( -1.0, 0.1, 1.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	y = pdf( NINF, 0.1, 1.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'the function evaluates the pdf for `x` given small parameters `c` and `d`', opts, function test( t ) {
	var expected;
	var x;
	var c;
	var d;
	var y;
	var i;

	expected = small.expected;
	x = small.x;
	c = small.c;
	d = small.d;
	for ( i = 0; i < x.length; i++ ) {
		y = pdf( x[i], c[i], d[i] );
		if ( y === expected[i] ) {
			t.equal( y, expected[i], 'x: '+x[i]+'. c: '+c[i]+'. d: '+d[i]+', y: '+y+', expected: '+expected[i] );
		} else {
			t.ok( isAlmostSameValue( y, expected[ i ], 5 ), 'within tolerance. x: '+x[ i ]+'. c: '+c[i]+'. d: '+d[i]+'. y: '+y+'. E: '+expected[ i ]+'.' );
		}
	}
	t.end();
});

